      "random_user.about_title": "About Random User Generator",
      "random_user.about_text": "Generate high-quality mock user data for your application tests and designs. This tool creates realistic profiles including names, emails, age, country, and profession. All data is generated locally in your browser using cryptographically secure random values.",
