      "vcard.about_title": "About vCard Generator",
      "vcard.about_text": "vCard is a file format standard for electronic business cards. vCards are often attached to e-mail messages, but can be exchanged in other ways, such as on the World Wide Web or via QR codes. This tool allows you to generate a valid vCard 3.0 file and a scannable QR code from your contact details.",
