      "pigenerator.about_title": "About Pi Digits",
      "pigenerator.about_text": "Pi (π) is the ratio of a circle's circumference to its diameter. It is an irrational number, meaning its decimal representation never ends and never settles into a permanent repeating pattern. This tool allows you to view and format the first 2,000 digits of Pi.",
      "edigits.about_title": "About Euler's Number",
      "edigits.about_text": "Euler's number (e) is a mathematical constant approximately equal to 2.71828 which is the base of the natural logarithm. It is the limit of (1 + 1/n)ⁿ as n approaches infinity. This tool allows you to view and format the first 2,000 digits of e.",
      "phidigits.about_title": "About Golden Ratio",
      "phidigits.about_text": "The Golden Ratio (φ) is a mathematical constant approximately equal to 1.61803. Two quantities are in the golden ratio if their ratio is the same as the ratio of their sum to the larger of the two quantities. This tool allows you to view and format the first 2,000 digits of phi.",
