      "bcd.about_title": "About Binary Coded Decimal",
      "bcd.about_text": "Binary Coded Decimal (BCD) is a class of binary encodings of decimal numbers where each decimal digit is represented by a fixed number of bits, usually four. In the 8421 BCD encoding, each decimal digit is represented by its four-bit binary equivalent.",
