      "excess3.about_title": "About Excess-3 Code",
      "excess3.about_text": "Excess-3 code (also called XS-3, 3-excess code or Stibitz code) is a non-weighted BCD code. It is obtained by adding 3 to each decimal digit and then representing the sum as a 4-bit binary number. It is a self-complementing code.",
