      "find_replace.about_title": "About Find and Replace",
      "find_replace.about_text": "This tool allows you to quickly search for specific text and replace it with something else. You can use standard text matching or Regular Expressions for more complex patterns. The process is entirely local to your browser.",
      "imageresizer.about_title": "About Image Resizer",
      "imageresizer.about_text": "Resize your images to exact pixel dimensions or by percentage. You can lock the aspect ratio to prevent distortion. All processing is done locally in your browser using the HTML5 Canvas API, meaning your images are never uploaded to any server.",
      "emojitoimage.about_title": "About Emoji to Image",
      "emojitoimage.about_text": "Convert any emoji into a high-resolution image file. Perfect for creating custom icons or stickers. The tool uses your system's native emoji font to render the graphics at high quality. PNG export supports transparency, while JPEG export is better for smaller file sizes with a solid background.",
      "numtransformer.about_title": "About Number Transformer",
      "numtransformer.about_text": "This utility allows you to perform batch mathematical operations on lists of numbers. You can reverse digits, increment or decrement all numbers by a specific value, and add or remove thousands separators. The tool preserves the surrounding text, making it ideal for processing numbers within log files or structured data.",
      "negabinary.about_title": "What is Negabinary?",
      "negabinary.about_text": "Negabinary is a non-standard positional numeral system with base -2. Unlike standard binary (base 2), negabinary can represent both positive and negative integers without using a sign bit.",
