      "cssclamp.what_is_title": "What is CSS clamp()?",
      "cssclamp.what_is_text": "The clamp() CSS function clamps a middle value between a range of values between a defined minimum bound and a maximum bound. The function takes three parameters: a minimum value, a preferred value, and a maximum allowed value.",
      "cssclamp.how_it_works_title": "How it works?",
      "cssclamp.how_it_works_text": "This tool calculates the linear interpolation (slope and y-axis intercept) between your minimum and maximum values relative to the viewport widths. It generates the optimal clamp() function to ensure smooth scaling.",
      "cssclamp.advantages_title": "Advantages",
      "cssclamp.advantages_text": "Fluid typography and spacing without using hundreds of media queries. It makes your design truly responsive and maintains visual harmony across all devices.",
      "b64hex.error_odd_hex": "Hex string must have an even number of characters",
      "b64hex.what_is_title": "About this conversion",
      "b64hex.what_is_text": "Base64 and Hexadecimal are two different ways to represent binary data. This tool allows you to switch between them instantly. Each hex pair represents one byte, which is then encoded into Base64 characters.",
      "b64hex.base64_title": "Base64 Encoding",
      "b64hex.base64_text": "Base64 uses 64 characters (A-Z, a-z, 0-9, +, /) to represent data. It is widely used to embed binary data in text environments like HTML, CSS or JSON.",
      "b64hex.hex_title": "Hexadecimal (Base16)",
      "b64hex.hex_text": "Hexadecimal uses 16 symbols (0-9 and A-F). It's the most common way for developers to view raw binary data, as each byte is represented by exactly two hex characters.",
