      "dogage.about_title": "How is dog age calculated?",
      "dogage.about_text": "The common belief that one dog year equals 7 human years is a simplification. In reality, dogs mature faster at the beginning of their lives. The first year counts for about 15 years, the second for 9, and then each additional year counts for 4 to 7 years depending on the size and breed of the animal.",
