      "lookandsay.about_title": "What is the 'Look-and-Say' sequence?",
      "lookandsay.about_text": "The Conway sequence (or Look-and-Say) is a mathematical sequence where each term is constructed by reading the digits of the previous term aloud. For example, if the term is '1', we read 'one 1', so the next is '11'. '11' reads as 'two 1s', so '21'. '21' reads as 'one 2, one 1', so '1211', and so on.",
