      "csstotailwind.about_text": "This utility automatically maps standard CSS properties (layout, sizing, typography, spacing, borders, background, flexbox/grid, effects, and positioning) to their equivalent Tailwind CSS utility classes. If a value does not exactly match a default Tailwind spacing or sizing step, it can be mapped to an arbitrary Tailwind v3 value (e.g. `[17px]`), preserving your styles while transitioning to utility-first styling.",
      "sqlminifier.about_title": "About SQL Minifier",
