      "base64_to_file.about_title": "About Base64 to File",
      "base64_to_file.about_text": "Convert Base64 encoded strings back into their original file format. This tool supports any file type. If your input includes a Data URL prefix, it will be automatically handled. You can specify a filename and an optional MIME type to ensure the browser correctly identifies the downloaded file.",
      "numberconverter.custom_base": "Custom Base Conversion",
      "numberconverter.base_label": "Base",
      "numberconverter.value_in_base": "Value in base {{base}}",
      "numberconverter.custom_placeholder": "Enter value...",
      "numberconverter.about_text_extended": "This tool supports conversion between any base from 2 to 36. It uses BigInt for arbitrary-precision arithmetic, allowing you to convert extremely large numbers without losing a single bit of information.",
      "palindromic.mode_range": "Range",
      "palindromic.mode_length": "Length",
      "palindromic.digit_length": "Digit Length",
