      "palindromic.waiting": "Configure options to see palindromic numbers...",
      "palindromic.about_title": "About Palindromic Numbers",
      "palindromic.about_text": "A palindromic number (also known as a numeral palindrome or a numeric palindrome) is a number that remains the same when its digits are reversed. For example, 121 or 12321. This tool helps you find all palindromic numbers in a specific numeric range or generate random ones of a specific length.",
      "asciidecimal.about_title": "About ASCII/Decimal conversion",
      "asciidecimal.about_text": "This tool provides a bidirectional mapping between text characters and their corresponding decimal codes. It uses the Unicode standard, which covers standard ASCII (0-127) as well as extended characters and emojis. Each character is represented by its numeric 'code point'.",
      "bitshifter.shift_type": "Shift Type",
      "bitshifter.amount": "Shift Amount",
      "bitshifter.about_title": "About Bit Shifting",
      "bitshifter.about_text": "Bitwise shifting moves each bit in a binary string to the left or right. Logical shifts fill the empty spots with zeros. Arithmetic right shifts preserve the sign bit (the most significant bit). Circular rotations (ROL/ROR) move the bits that 'fall off' one end back to the other end.",
      "jsonflattener.about_title": "About JSON Flattening",
      "jsonflattener.about_text": "Flattening converts nested JSON into a single-level object. For example, {a: {b: 1}} becomes {\"a.b\": 1}. This is useful for processing JSON in environments that only support flat key-value pairs, like some spreadsheets or simple databases.",
      "jsonunflattener.about_title": "About JSON Unflattener",
      "jsonunflattener.about_text": "Unflattening is the reverse of flattening. It takes a flat JSON object where keys represent paths (e.g., 'a.b.c') and converts it back into a nested JSON structure. This is useful when working with data from systems that only support flat key-value pairs but represent hierarchy via dot notation.",
      "jsonsortkeys.sort_order": "Sort Order",
      "jsonsortkeys.ascending": "Ascending (A-Z)",
      "jsonsortkeys.descending": "Descending (Z-A)",
      "jsonsortkeys.recursive": "Recursive Sort",
      "jsonsortkeys.about_title": "About JSON Key Sorter",
      "jsonsortkeys.about_text": "This tool allows you to sort the keys of a JSON object alphabetically. Sorting keys is extremely helpful when comparing two JSON files to see actual data differences without being distracted by key order. It can recursively sort nested objects and arrays of objects.",
      "sierpinski.about_title": "About Sierpinski Triangle",
      "sierpinski.about_text": "The Sierpinski triangle is a self-similar fractal pattern that is a mathematically generated pattern that can be reproducible at any magnification or reduction. It is named after the Polish mathematician Wacław Sierpiński who described it in 1915.",
      "jsonstringifier.about_title": "JSON Stringifier & Parser",
      "jsonstringifier.about_text": "This tool converts a JSON object into a double-quoted string with escaped characters, which is often required when including JSON inside other JSON structures or as string literals in source code. It also performs the reverse operation.",
      "htmlstripper.about_title": "About HTML Stripper",
      "htmlstripper.about_text": "This tool removes all HTML tags and attributes from your input, leaving only the text content. It uses the browser's native DOM parser for high-performance and reliable stripping of tags like <div>, <span>, <a>, etc.",
