      "hex_endianness.about_text": "Endianness refers to the order in which bytes are arranged within larger data units (words) in computer memory. Big-endian stores the most significant byte first, while little-endian stores the least significant byte first. This tool allows you to swap between these formats by reversing the byte order within each word.",
      "grapheme_extractor.extracted_title": "Extracted Graphemes",
      "grapheme_extractor.about_title": "About Grapheme Extraction",
      "grapheme_extractor.about_text": "A grapheme is the smallest functional unit of a writing system. While a 'character' in code often refers to a single Unicode code point, user-perceived characters (like combined emojis or accented letters) can consist of multiple code points. This tool uses the Intl.Segmenter API to correctly identify these units.",
