      "properties_json.unflatten": "Unflatten Keys",
      "properties_json.about_title": "About Properties to JSON",
      "properties_json.about_text": "Convert Java-style .properties files into structured JSON. It supports both = and : separators, comments starting with # or !, and automatic unflattening of dot-notation keys (e.g., app.name becomes a nested object). The tool also features prototype pollution protection for secure unflattening.",
      "ndjson.to_ndjson": "To NDJSON",
      "ndjson.to_json": "To JSON Array",
      "ndjson.about_title": "About NDJSON (Newline Delimited JSON)",
      "ndjson.about_text": "NDJSON is a format for storing or streaming structured data. Each line in the file is a valid JSON object, separated by a newline character. It is ideal for large datasets and log files because it allows processing data one line at a time without loading the entire file into memory.",
      "json_latex.hlines": "hlines",
      "json_latex.vlines": "vlines",
      "json_latex.about_title": "About JSON to LaTeX Table",
      "json_latex.about_text": "This tool converts a JSON array of objects into a LaTeX tabular environment. It handles automatic escaping of special LaTeX characters like &, %, and $. You can toggle horizontal (\\hline) and vertical lines according to your document style. Perfect for academic papers and technical documentation.",
      "json_avro.about_title": "About JSON to Avro Schema",
      "json_avro.about_text": "Apache Avro is a data serialization system. Avro relies on schemas, which are defined in JSON. This tool helps you convert your sample JSON data into an Avro schema definition (.avsc), automatically inferring types and handling nested structures.",
      "ipconverter.invalid_ip": "Invalid IPv4 address",
      "ipconverter.invalid_decimal": "Invalid Decimal IP",
      "ipconverter.about_title": "About IP Conversion",
      "ipconverter.about_text": "An IPv4 address is essentially a 32-bit number. While we usually write it in dotted-decimal notation (e.g., 192.168.1.1) for human readability, computers often process it as a single integer, a hexadecimal value, or a raw binary string. This tool helps you convert between these different representations.",
      "tsv_json.about_title": "About TSV <> JSON Conversion",
      "tsv_json.about_text": "Tab-Separated Values (TSV) is a common format for exchanging tabular data. This tool allows for bidirectional conversion between TSV and JSON arrays. It automatically detects types and handles escaping correctly.",
      "tsv_csv.about_title": "About TSV <> CSV Conversion",
      "tsv_csv.about_text": "Convert between Tab-Separated Values (TSV) and Comma-Separated Values (CSV). TSV is often used in spreadsheets and databases, while CSV is a universal standard for data exchange. This tool ensures proper field delimitation and quoting.",
      "svg_to_image.source": "SVG Source",
