      "xml_yaml.about_title": "About XML <> YAML Converter",
      "xml_yaml.about_text": "Convert your data between XML and YAML formats. This tool uses native browser APIs for XML parsing and serialization, ensuring high performance and security. YAML handling is powered by the js-yaml library.",
      "xml_yaml.tech_title": "Technical details",
      "xml_yaml.tech_text": "Attributes in XML are represented with a '@' prefix in YAML. Text content is represented by the '#text' key if the element also has attributes or sub-elements. The tool implements recursive depth limits and sanitizes keys to prevent prototype pollution.",
      "common.bidirectional_sync": "Bidirectional Sync Enabled",
      "tool.hill-cipher.name": "Hill Cipher",
      "tool.hill-cipher.description": "Encrypt and decrypt text using the matrix-based Hill cipher",
      "hillcipher.matrix_size": "Matrix Size",
      "hillcipher.error_invertible": "The matrix must be invertible modulo 26 (determinant must be coprime to 26).",
      "hillcipher.about_title": "About Hill Cipher",
      "hillcipher.about_text": "The Hill cipher is a polyalphabetic substitution cipher based on linear algebra, invented by Lester S. Hill in 1929. It uses a square matrix as a key to transform blocks of text. For decryption to be possible, the matrix must be invertible modulo 26, meaning its determinant must not be divisible by 2 or 13.",
      "jsonini.about_title": "About JSON <> INI Converter",
      "jsonini.about_text": "This tool allows you to convert between JSON and INI configuration formats. INI files are simple text files with a basic structure composed of sections, properties, and values. JSON is a more complex, hierarchical format. This converter automatically maps JSON nested objects to INI sections.",
      "jsontosql.error_invalid_fields": "Enter valid JSON with fields to select columns",
      "jsontosql.error_invalid_json": "Enter valid JSON to select columns",
      "baconian.mode_label": "Baconian Variant",
      "baconian.mode_desc": "Choose between I/J=I and U/V=U (Standard) or full 26 letters (Extended)",
      "baconian.reference_title": "Baconian Mapping",
      "baconian.about_title": "About Baconian",
      "baconian.about_text": "The Baconian cipher is a method of steganography devised by Francis Bacon in 1605. It replaces each letter of the plaintext with a sequence of 5 characters, originally using different typefaces (A/B) to hide the message.",
      "baconian.variants_title": "Standard vs Extended",
      "baconian.variants_text": "The standard version uses the same code for I/J and U/V (as was common in 17th century Latin). The extended version provides unique 5-bit codes for all 26 letters of the modern English alphabet.",
      "polybius.config": "Square Configuration",
      "polybius.size": "Grid Size",
      "polybius.key_placeholder": "OPTIONAL KEYWORD...",
      "polybius.about_title": "About Polybius Square",
      "polybius.about_text": "The Polybius Square is a device invented by the ancient Greek historian Polybius. It works by replacing each letter with its coordinates in a grid (usually 5x5 for the English alphabet, combining I and J).",
      "polybius.variants_title": "Custom Grids",
      "polybius.variants_text": "While the 5x5 grid is standard, a 6x6 grid can include both letters and numbers. Adding a keyword shuffles the grid, making it much harder to crack without knowing the secret key.",
      "affine.keys_title": "Cipher Keys",
      "affine.formula": "Formula: E(x) = (ax + b) mod 26",
      "affine.about_title": "About Affine Cipher",
      "affine.about_text": "The Affine cipher is a type of monoalphabetic substitution cipher, where each letter in an alphabet is mapped to its numeric equivalent, encrypted using a simple mathematical function, and converted back to a letter.",
      "affine.security_title": "Security Requirement",
      "affine.security_text": "For the cipher to be reversible, the key \"a\" must be coprime to the size of the alphabet (26). This means GCD(a, 26) must equal 1. Key \"b\" can be any integer.",
      "jsdoc.output_label": "JSDoc Typedefs",
