      "xor.about_title": "About XOR Cipher & Bitwise Operations",
      "xor.about_text": "XOR (exclusive OR) is a logical operation on bits. The bitwise XOR operation compares each bit of the input bytes with the corresponding bit of the key bytes. If the bits are different, the output bit is 1; if they are the same, the output is 0. Repeating-key XOR applies the key cyclically over the input length, making it a simple yet highly effective obfuscation tool often used in reverse engineering, binary analysis, and cryptographic proofs.",
