      "collatz.about_title": "About the Collatz Conjecture",
      "collatz.about_text": "The Collatz Conjecture is one of the most famous unsolved problems in mathematics. Also known as the 3n + 1 problem, it starts with any positive integer n. If n is even, divide it by 2. If n is odd, multiply it by 3 and add 1. The conjecture asserts that no matter what number you start with, you will always eventually reach 1. This visualizer provides rich step analytics, peak evaluations, and logarithmic trend paths.",
