      "jsontomermaid.what_is_title": "Quel est cet outil ?",
      "jsontomermaid.what_is_text": "Convertissez vos structures de données JSON en code de diagramme Mermaid.js. Mermaid est un langage de script de type markdown pour générer des graphiques et des diagrammes. Cet outil vous aide à visualiser les objets imbriqués complexes et leurs relations.",
      "jsontomermaid.modes_title": "Modes de Diagramme",
      "jsontomermaid.class_desc": "Affiche les objets sous forme de classes avec des propriétés typées et des relations de composition.",
      "jsontomermaid.mindmap_desc": "Visualise le JSON comme un arbre hiérarchique ou une carte mentale, parfait pour voir les niveaux d'imbrication.",
      "jsontomermaid.usage_title": "Comment utiliser ?",
      "jsontomermaid.usage_text": "Collez votre JSON à gauche. Le code Mermaid est généré instantanément à droite. Vous pouvez ensuite copier ce code et le coller dans n'importe quel éditeur compatible Mermaid (comme Notion, GitHub ou l'éditeur en ligne Mermaid) pour rendre le graphique.",
      "tomljson.what_is_toml": "Qu'est-ce que le TOML ?",
      "tomljson.toml_desc": "TOML (Tom's Obvious, Minimal Language) est un format de fichier de configuration facile à lire grâce à une sémantique évidente. Il est conçu pour correspondre sans ambiguïté à une table de hachage. Il est largement utilisé dans les environnements de développement modernes, en particulier dans l'écosystème Rust (Cargo.toml) et pour divers générateurs de sites statiques.",
      "tomljson.how_it_works": "Comment ça marche ?",
      "tomljson.how_text": "Cet outil vous permet de convertir instantanément entre les formats TOML et JSON. Au fur et à mesure que vous tapez dans un champ, l'autre est mis à jour automatiquement. Notez que la racine d'un document TOML doit être une table (paires clé-valeur), donc l'entrée JSON doit être un objet.",
      "valibot.what_is_title": "Qu'est-ce que Valibot ?",
      "valibot.what_is_text": "Valibot est une bibliothèque de validation de schéma modulaire et typée pour TypeScript. Elle est conçue pour être extrêmement légère en utilisant une approche fonctionnelle qui permet un excellent tree-shaking.",
      "valibot.how_it_works_title": "Comment ça marche ?",
      "valibot.how_it_works_text": "L'outil analyse votre JSON et génère le code TypeScript correspondant en utilisant les fonctions Valibot (v.string(), v.number(), v.object(), etc.). Il fournit également automatiquement le type inféré.",
      "valibot.advantages_title": "Avantages",
      "valibot.advantages_text": "En utilisant Valibot, vous obtenez un impact minimal sur la taille du bundle par rapport à d'autres bibliothèques comme Zod, tout en conservant une sécurité de type complète et un riche écosystème de règles de validation.",
      "wordcounter.reading_speed.average": "Moyenne",
      "wordcounter.reading_speed.fast": "Rapide",
      "wordcounter.btn.uppercase": "MAJUSCULES",
      "wordcounter.btn.lowercase": "minuscules",
      "wordcounter.btn.capitalize": "Capitaliser",
      "wordcounter.btn.sentence_mode": "Mode phrase",
      "wordcounter.top_words": "Mots les plus fréquents (Densité)",
      "wordcounter.top_bigrams": "Groupes de 2 mots (Bigrammes)",
