      "wordcounter.char_freq": "Fréquence des caractères",
      "wordcounter.char_freq_report": "Fréquence des caractères",
      "wordcounter.report_title": "Rapport de texte",
      "wordcounter.flesch_title": "Score de lisibilité Flesch",
      "wordcounter.flesch_subtitle": "Basé sur la formule adaptée au français",
      "wordcounter.flesch_description": "Un score élevé (90-100) indique un texte très facile à lire, tandis qu'un score bas (0-30) correspond à un texte académique ou technique complexe.",
      "wordcounter.density_title": "Densité de mots",
      "wordcounter.density_description": "La densité de mots vous aide à identifier les termes répétitifs. C'est un indicateur clé pour l'optimisation SEO et la qualité rédactionnelle afin d'éviter les répétitions excessives.",
      "wordcounter.social_title": "Réseaux Sociaux",
      "wordcounter.guide_title": "Guide d'utilisation",
      "wordcounter.guide_text": "Collez simplement votre texte dans la zone de saisie. Les statistiques se mettent à jour instantanément. Vous pouvez utiliser les boutons pour changer la casse du texte ou copier les rapports de statistiques détaillés.",
      "wordcounter.tech_title": "Détails Techniques",
      "wordcounter.tech_text": "Le comptage des mots utilise une expression régulière robuste pour identifier les séparateurs. Le temps de lecture est estimé sur une base de 200 mots/minute, tandis que le temps de parole est calculé sur 130 mots/minute.",
      "wordcounter.faq_text": "Mes données sont-elles privées ? Absolument. Aucun texte n'est envoyé à un serveur. Tout le traitement est effectué localement sur votre appareil.",
