      "jsontoswift.about_title": "À propos de la conversion JSON en Swift",
      "jsontoswift.about_text": "Cet outil génère des structures Swift conformes au protocole Codable à partir de vos données JSON. Il gère automatiquement les objets imbriqués et les tableaux, en utilisant les types Swift standards comme String, Int, Double et Bool.",
      "jsontoruby.about_title": "À propos de la conversion JSON en Ruby",
      "jsontoruby.about_text": "Cet outil génère des classes Ruby avec des accesseurs de données (attr_accessor) à partir de vos données JSON. Il gère les types de base et les objets imbriqués, en suivant les conventions de nommage Ruby (snake_case pour les méthodes et variables, PascalCase pour les classes).",
      "jsontoscala.about_title": "À propos de la conversion JSON en Scala",
      "jsontoscala.about_text": "Cet outil génère des case classes Scala à partir de vos données JSON. Idéal pour le développement avec Play Framework, Akka ou Spark. Il gère les types Option pour les valeurs nulles et les List pour les tableaux.",
      "yamljson.about_title": "À propos de la conversion YAML/JSON",
      "yamljson.about_text1": "YAML et JSON sont deux formats de sérialisation de données largement utilisés. Le YAML est souvent privilégié pour les fichiers de configuration grâce à sa lisibilité, tandis que le JSON est le standard pour les échanges de données via API.",
      "yamljson.about_text2": "Comme tous nos outils, la conversion s'effectue localement dans votre navigateur. Aucune donnée n'est transmise à nos serveurs, garantissant ainsi la confidentialité de vos fichiers de configuration.",
