      "vcard.about_title": "À propos du Générateur vCard",
      "vcard.about_text": "Le vCard est un format standard de fichier pour les cartes de visite électroniques. Les vCards sont souvent jointes aux messages électroniques, mais peuvent être échangées par d'autres moyens, comme sur le Web ou via des codes QR. Cet outil vous permet de générer un fichier vCard 3.0 valide et un code QR scannable à partir de vos coordonnées.",
      "tool.words-to-numbers.name": "Mots en Nombres",
      "tool.words-to-numbers.description": "Convertir des nombres écrits en anglais en chiffres",
      "wordstonumbers.input_label": "Nombre en lettres (Anglais)",
      "wordstonumbers.error_invalid": "Mots non valides",
      "wordstonumbers.about_title": "À propos de la conversion Mots en Nombres",
      "wordstonumbers.about_text": "Cet outil convertit les nombres écrits en anglais en leur représentation numérique. Il gère les unités, les dizaines, les centaines et les échelles jusqu'aux trillions.",
      "tool.pi-generator.name": "Décimales de Pi",
      "tool.pi-generator.description": "Générer et formater les décimales de Pi (π)",
      "pigenerator.digits": "Chiffres",
      "pigenerator.grouping": "Groupement",
      "pigenerator.about_title": "À propos des décimales de Pi",
      "pigenerator.about_text": "Pi (π) est le rapport entre la circonférence d'un cercle et son diamètre. C'est un nombre irrationnel. Cet outil vous permet de visualiser et de formater les 2 000 premières décimales de Pi.",
      "edigits.about_title": "À propos du nombre d'Euler",
      "edigits.about_text": "Le nombre d'Euler (e) est une constante mathématique approximativement égale à 2,71828 qui est la base du logarithme népérien. Cet outil vous permet de visualiser et de formater les 2 000 premières décimales de e.",
      "phidigits.about_title": "À propos du Nombre d'Or",
      "phidigits.about_text": "Le nombre d'or (φ) est une constante mathématique approximativement égale à 1,61803. Cet outil vous permet de visualiser et de formater les 2 000 premières décimales de phi.",
      "bcd.decimal_label": "Décimal",
      "bcd.bcd_label": "BCD (8421)",
      "bcd.error_invalid_decimal": "Entrée décimale non valide. Seuls les entiers positifs sont autorisés.",
      "bcd.error_invalid_bcd": "Entrée BCD non valide. Doit être des groupes de 4 bits (0 ou 1).",
      "bcd.error_invalid_nibble": "Nibble BCD non valide : {{nibble}} est supérieur à 9.",
      "bcd.about_title": "À propos du Décimal Codé Binaire",
      "bcd.about_text": "Le Décimal Codé Binaire (BCD) est une classe d'encodages binaires de nombres décimaux où chaque chiffre décimal est représenté par un nombre fixe de bits, généralement quatre. Dans l'encodage BCD 8421, chaque chiffre décimal est représenté par son équivalent binaire sur quatre bits.",
      "excess3.decimal_label": "Décimal",
      "excess3.excess3_label": "Excédent 3",
      "excess3.error_invalid_decimal": "Entrée décimale non valide. Seuls les entiers positifs sont autorisés.",
      "excess3.error_invalid_excess3": "Entrée Excédent 3 non valide. Doit être des groupes de 4 bits (0 ou 1).",
      "excess3.error_invalid_nibble": "Nibble Excédent 3 non valide : {{nibble}} ne représente pas un chiffre valide (0-9).",
      "excess3.about_title": "À propos du code Excédent 3",
      "excess3.about_text": "Le code Excédent 3 (également appelé XS-3 ou code de Stibitz) est un code BCD non pondéré. Il est obtenu en ajoutant 3 à chaque chiffre décimal, puis en représentant la somme sous forme de nombre binaire à 4 bits. C'est un code auto-complémentaire.",
      "tool.image-color-replacer.name": "Remplacer Couleur Image",
