      "lifecalendar.progress": "Progression de Vie",
      "lifecalendar.title_grid": "Vie en Semaines",
      "lifecalendar.waiting": "Entrez votre date de naissance pour voir votre calendrier de vie.",
      "lifecalendar.about_title": "À propos du Calendrier de Vie",
      "lifecalendar.about_text": "Un calendrier de vie, également connu sous le nom de graphique Memento Mori, représente votre vie en semaines. Chaque carré correspond à une semaine de votre vie. Cet outil aide à visualiser le temps et offre une perspective sur la part de vie déjà vécue et ce qui pourrait rester en fonction de l'espérance de vie moyenne. C'est un rappel puissant de la valeur de chaque instant.",
      "csvtosql.table_name": "Nom de la Table",
