      "binarybitwise.title": "Entrées Bit à Bit",
      "binarybitwise.val_a": "Valeur A",
      "binarybitwise.val_b": "Valeur B",
      "binarybitwise.about_title": "À propos des opérations bit à bit",
      "binarybitwise.about_text": "Les opérations bit à bit traitent les données comme une séquence de bits (0 et 1) plutôt que comme des valeurs numériques. Cet outil utilise BigInt pour supporter des nombres arbitrairement grands, ce qui est essentiel pour certaines tâches cryptographiques et de traitement de données. Les opérations comme AND, OR et XOR comparent les bits à chaque position, tandis que NOT inverse tous les bits.",
