      "texttooctal.octal": "Octal",
      "texttooctal.about_title": "À propos de la représentation octale",
      "texttooctal.about_text": "Le système de numération octale, ou base 8, utilise les chiffres de 0 à 7. Bien que moins courant aujourd'hui que l'hexadécimal, l'octal était largement utilisé dans les débuts de l'informatique et se retrouve encore dans les permissions de fichiers Unix. Cet outil convertit le point de code ASCII/Unicode de chaque caractère en son équivalent octal à 3 chiffres.",
      "numsorter.criterion": "Critère de tri",
      "numsorter.order": "Ordre",
