      "numsorter.crit_digit_count": "Nombre de chiffres",
      "numsorter.about_title": "À propos du Trieur de Nombres",
      "numsorter.about_text": "Cet outil vous permet de trier des listes de nombres selon divers critères mathématiques. Vous pouvez trier par valeur numérique standard, par valeur absolue (en ignorant les signes), par la somme de leurs chiffres individuels, ou par le nombre de chiffres qu'ils contiennent. Il gère plusieurs séparateurs tels que les virgules, les espaces ou les points-virgules.",
