      "clock.how_title": "À propos du Générateur d'Horloge",
      "clock.how_text": "Créez votre propre horloge personnalisée. Personnalisez les couleurs, activez ou désactivez l'aiguille des secondes, et choisissez entre les styles analogique et numérique. Pour la version analogique, vous pouvez même télécharger le résultat sous forme d'image PNG pour vos projets.",
      "uuid.count_label": "Nombre d'UUIDs à générer",
      "uuid.version_label": "Version",
      "uuid.empty_title": "Aucun UUID généré",
      "uuid.empty_hint": "Cliquez sur 'Générer' pour créer des identifiants uniques.",
      "uuid.about_title": "Qu'est-ce qu'un UUID ?",
      "uuid.about_text": "Un UUID (Universally Unique Identifier) est un identifiant unique de 128 bits utilisé pour identifier des informations de manière unique dans les systèmes informatiques sans coordination centrale. L'UUID v4 est aléatoire, tandis que l'UUID v7 est ordonné dans le temps.",
      "macgenerator.empty_title": "Aucune adresse MAC générée",
      "macgenerator.empty_hint": "Cliquez sur 'Générer' pour créer des adresses MAC aléatoires.",
      "macgenerator.about_title": "À propos des adresses MAC",
      "macgenerator.about_text": "Une adresse MAC (Media Access Control) est un identifiant unique attribué à une interface réseau pour les communications sur le segment de réseau physique. Ce générateur crée des adresses MAC aléatoires et valides, configurées comme des adresses administrées localement (LAA).",
