      "palindrome.about_text": "Un palindrome est un mot, une phrase ou une séquence de caractères qui se lit de la même manière dans les deux sens, en ignorant généralement la casse, les accents, la ponctuation et les espaces. Exemple : 'Radar', 'Laval', ou encore 'Ésope reste ici et se repose'.",
      "dogage.dog_years": "Âge du chien (années)",
