      "dogage.about_title": "Comment est calculé l'âge d'un chien ?",
      "dogage.about_text": "L'idée reçue qu'une année de chien équivaut à 7 années humaines est une simplification. En réalité, les chiens mûrissent plus vite au début de leur vie. La première année compte pour environ 15 ans, la deuxième pour 9, puis chaque année supplémentaire compte pour 4 à 7 ans selon la taille et la race de l'animal.",
      "lookandsay.seed": "Nombre de départ (Seed)",
