      "lookandsay.times": "fois le",
      "lookandsay.about_title": "Qu'est-ce que la suite 'Regarde et dis' ?",
      "lookandsay.about_text": "La suite de Conway (ou Look-and-Say) est une suite mathématique où chaque terme se construit en lisant à voix haute le terme précédent. Par exemple, si le terme est '1', on lit 'un 1', donc le suivant est '11'. '11' se lit 'deux 1', donc '21'. '21' se lit 'un 2, un 1', donc '1211', et ainsi de suite.",
