      "fractaltree.about_title": "À propos des arbres fractals",
      "fractaltree.about_text": "Cet outil utilise un algorithme récursif pour dessiner un arbre au rendu naturel. Chaque branche se divise en deux branches plus petites selon un angle défini. En ajustant les paramètres et en ajoutant un peu d'aléatoire, vous pouvez créer des motifs uniques allant de structures géométriques à des arbres réalistes.",
      "unicodenormalizer.input_label": "Texte Unicode Stylisé",
      "unicodenormalizer.output_label": "Texte Simple Normalisé",
      "unicodenormalizer.about_title": "À propos de la normalisation Unicode",
      "unicodenormalizer.about_text": "De nombreuses polices \"fantaisie\" en ligne utilisent les symboles alphanumériques mathématiques de la norme Unicode. Bien qu'ils ressemblent à des lettres, ce sont techniquement des symboles différents, ce qui peut nuire à la recherche et à l'accessibilité. Cet outil convertit ces symboles et autres caractères stylisés en leurs équivalents ASCII standard.",
