      "headerparser.about_text": "Cet outil vous aide à analyser et structurer rapidement les en-têtes de requête ou de réponse HTTP bruts. Il extrait les paires clé-valeur et les présente dans un tableau lisible ou au format JSON, facilitant le débogage des communications API, des en-têtes de sécurité (CSP, HSTS) ou des politiques de cache.",
      "headerparser.how_to_use_title": "Comment utiliser",
      "headerparser.how_to_use_text": "Copiez simplement les en-têtes bruts depuis l'onglet 'Réseau' de votre navigateur ou toute sortie de terminal et collez-les dans le champ de saisie. L'analyseur identifiera automatiquement les en-têtes et fournira instantanément une visualisation structurée.",
      "hilbert.order": "Ordre (Complexité)",
      "hilbert.stroke_width": "Épaisseur du trait",
      "hilbert.about_title": "À propos de la courbe de Hilbert",
      "hilbert.about_text": "La courbe de Hilbert est une courbe fractale continue remplissant l'espace, décrite pour la première fois par le mathématicien allemand David Hilbert en 1891. C'est une variante de courbe qui remplit une grille carrée en visitant chaque point exactement une fois sans jamais se croiser. Elle est utilisée en traitement d'image, en compression de données et pour l'indexation multidimensionnelle car elle préserve bien la localité des données.",
      "obfuscator.prefix": "Préfixe des clés",
      "obfuscator.id_length": "Longueur de l'ID",
      "obfuscator.about_title": "À propos de l'obfuscateur JSON",
      "obfuscator.about_text": "Cet outil obfusque les données JSON en renommant récursivement toutes les clés d'objet par de courtes chaînes aléatoires. C'est une forme de sécurité basique par l'obscurité, rendant la structure JSON difficile à lire pour un humain tout en restant un JSON valide pour un traitement informatique. Note : cela ne crypte pas les valeurs, seulement les clés.",
      "wordshuffler.placeholder": "Collez votre texte ici pour mélanger les mots...",
      "wordshuffler.about_title": "À propos du mélangeur de mots",
      "wordshuffler.about_text": "Cet outil mélange l'ordre des mots dans chaque ligne de votre texte. C'est utile pour créer des anagrammes au niveau des mots, générer des phrases aléatoires pour des tests, ou simplement brouiller un texte tout en conservant la structure ligne par ligne.",
      "softshadow.layers": "Nombre de couches",
      "softshadow.transparency": "Transparence finale",
      "softshadow.blur": "Flou maximum",
      "softshadow.spread": "Diffusion (Spread)",
      "softshadow.about_title": "À propos des ombres douces",
      "softshadow.about_text": "Ce générateur crée des ombres de texte ou de boîte réalistes et 'douces' en superposant plusieurs couches d'ombres avec des opacités et des flous croissants. Cette technique évite l'aspect 'sale' des ombres CSS uniques standards et donne un rendu plus professionnel proche de la réalité physique.",
      "jsontopydantic.about_title": "À propos de JSON en Pydantic",
      "jsontopydantic.about_text": "Générez des modèles Pydantic V2 à partir de vos données JSON. L'outil gère automatiquement la conversion des clés en snake_case (convention Python) et utilise des alias pour préserver la compatibilité avec le JSON d'origine. Les objets imbriqués sont extraits en classes distinctes.",
      "jsontodjango.about_title": "À propos du convertisseur JSON en modèles Django",
      "jsontodjango.about_text": "Convertissez des objets ou des payloads JSON complexes directement en structures de classes de modèles Python Django propres. Les objets imbriqués et les modèles relationnels sont extraits dans leurs propres définitions de modèles et liés dynamiquement via des descripteurs de relations OneToOneField ou ForeignKey avec des cascades.",
      "csstotailwind.options": "Options",
      "csstotailwind.use_arbitrary": "Utiliser des valeurs arbitraires pour les règles non-standards (ex: p-[17px])",
      "csstotailwind.prefix_className": "Formater en JSX className (className=\"...\")",
      "csstotailwind.input_label": "Déclarations CSS",
      "csstotailwind.output_label": "Classes Tailwind",
      "csstotailwind.placeholder": "Collez vos styles CSS ici... ex :\nbackground-color: #3b82f6;\npadding: 16px 24px;\nborder-radius: 8px;\ndisplay: flex;\nalign-items: center;",
      "csstotailwind.empty_output": "Les classes Tailwind CSS apparaîtront ici...",
      "csstotailwind.about_title": "À propos de Convertisseur CSS en Tailwind",
      "csstotailwind.about_text": "Cet outil associe automatiquement les propriétés CSS standard (mise en page, taille, typographie, espacement, bordures, arrière-plans, flexbox/grid, effets et positionnement) aux classes utilitaires correspondantes de Tailwind CSS. Si une valeur ne correspond pas exactement à un intervalle par défaut de Tailwind, elle peut être convertie en valeur arbitraire Tailwind v3 (ex: `[17px]`), préservant ainsi vos styles tout en adoptant une approche utilitaire.",
      "sqlminifier.about_title": "À propos du minificateur SQL",
      "sqlminifier.about_text": "Réduisez la taille de vos scripts SQL en supprimant les commentaires (mono-ligne et multi-lignes) et en compressant les espaces inutiles. Idéal pour optimiser les requêtes envoyées via réseau ou intégrées dans du code source.",
      "base64audio.about_title": "À propos de Base64 en Audio",
      "base64audio.about_text": "Convertissez des chaînes encodées en Base64 en un lecteur audio fonctionnel. Supporte les formats MP3, WAV et OGG. Pratique pour tester des flux audio provenant d'APIs ou de bases de données sans avoir à créer un fichier manuellement.",
      "base64audio.input_label": "Chaîne Audio Base64",
      "base64audio.decoded_title": "Audio Décodé",
      "base64audio.ready": "Prêt à être lu",
      "base64audio.player_label": "Lecteur Interactif",
