      "securityheaders.permissions_desc": "Désactive les APIs navigateur",
      "securityheaders.why_title": "Pourquoi ces en-têtes ?",
      "securityheaders.why_text": "Les en-têtes de sécurité HTTP indiquent au navigateur comment se comporter lors de l'interaction avec votre site. Ils constituent une première ligne de défense essentielle contre les vulnérabilités courantes comme le Cross-Site Scripting (XSS) et le détournement de session.",
      "securityheaders.recommendations_title": "Recommandations",
      "securityheaders.recommendations_text": "Il est fortement conseillé d'utiliser au minimum <1>HSTS</1>, <3>X-Content-Type-Options</3> et une <5>CSP</5> basique. Testez toujours vos configurations dans un environnement de pré-production avant de les déployer.",
      "duration.input_title": "Saisie des durées",
