      "duration.total_minutes": "Total Minutes",
      "duration.total_hours": "Total Heures",
      "duration.info_text": "Utilisez ce calculateur pour additionner des durées de vidéos, des temps de travail ou des intervalles de temps. Vous pouvez également soustraire des durées en cliquant sur le bouton plus/moins.",
      "duration.format_title": "Format Temporel",
      "duration.format_text": "Le format HH:MM:SS (Heures:Minutes:Secondes) est le standard sexagésimal. Notre outil gère automatiquement les reports (60 secondes = 1 minute, 60 minutes = 1 heure).",
      "duration.mixed_ops_title": "Opérations Mixtes",
      "duration.mixed_ops_text": "Vous pouvez mélanger les additions et les soustractions. C'est idéal pour calculer un temps de présence effectif en soustrayant les temps de pause du total.",
      "duration.conversions_title": "Conversions",
      "duration.conversions_text": "En plus du format standard, l'outil convertit automatiquement le total en minutes décimales et en heures décimales, ce qui est utile pour les logiciels de paie ou de facturation.",
