      "bio.generate": "Générer une nouvelle Bio",
      "bio.result_title": "Bio Générée",
      "bio.placeholder": "Votre bio apparaîtra ici...",
      "bio.about_title": "À propos du Générateur de Bio",
      "bio.about_text": "La première impression est cruciale. Cet outil vous aide à créer des biographies captivantes pour vos profils sociaux. Choisissez un style qui correspond à votre personnalité ou à votre marque, et générez une base à personnaliser. N'oubliez pas de rester authentique !",
      "tool.list-to-checklist.name": "Liste en Checklist",
      "tool.list-to-checklist.description": "Transformez vos listes en checklists Markdown, HTML ou textuelles",
      "checklist.input_label": "Votre Liste (un élément par ligne)",
      "checklist.placeholder": "Lait\nOeufs\nPain\nPommes...",
      "checklist.output_label": "Checklist Convertie",
      "checklist.format_label": "Format",
      "checklist.remove_empty": "Supprimer les lignes vides",
      "checklist.remove_empty_desc": "Ignorer automatiquement les lignes sans texte",
      "checklist.trim_lines": "Nettoyer les espaces",
      "checklist.trim_lines_desc": "Supprimer les espaces en début et fin de ligne",
      "checklist.about_title": "À propos du Générateur de Checklist",
      "checklist.about_text": "Transformez rapidement vos notes et listes en checklists structurées. Cet outil est idéal pour préparer des listes de tâches pour les éditeurs Markdown, des projets de code (HTML) ou simplement rendre des listes textuelles professionnelles pour des emails et de la documentation.",
      "list_to_json.input_label": "Votre Liste (un élément par ligne)",
      "list_to_json.placeholder": "Élément 1\nÉlément 2\nÉlément 3...",
      "list_to_json.about_title": "À propos de Liste en JSON",
      "list_to_json.about_text": "Convertissez rapidement n'importe quelle liste de texte brut en un tableau JSON formaté. Cet outil est parfait pour les développeurs qui ont besoin de transformer une liste de chaînes en une structure de données pour des fichiers de configuration, des données de test ou des constantes de code.",
      "base64_to_file.input_label": "Chaîne Base64",
      "base64_to_file.filename": "Nom du fichier",
      "base64_to_file.mimetype": "Type MIME (Optionnel)",
      "base64_to_file.mimetype_hint": "Exemple : image/png, application/pdf, text/plain",
      "base64_to_file.download": "Télécharger le Fichier",
      "base64_to_file.about_title": "À propos de Base64 en Fichier",
      "base64_to_file.about_text": "Convertissez des chaînes encodées en Base64 dans leur format de fichier d'origine. Cet outil prend en charge tous les types de fichiers. Si votre entrée inclut un préfixe Data URL, il sera automatiquement géré. Vous pouvez spécifier un nom de fichier et un type MIME facultatif pour vous assurer que le navigateur identifie correctement le fichier téléchargé.",
      "numberconverter.custom_base": "Conversion de Base Personnalisée",
      "numberconverter.base_label": "Base",
      "numberconverter.value_in_base": "Valeur en base {{base}}",
      "numberconverter.custom_placeholder": "Entrez une valeur...",
      "numberconverter.about_text_extended": "Cet outil prend en charge la conversion entre n'importe quelle base de 2 à 36. Il utilise BigInt pour une arithmétique de précision arbitraire, vous permettant de convertir des nombres extrêmement grands sans perdre un seul bit d'information.",
      "palindromic.mode_range": "Intervalle",
      "palindromic.mode_length": "Longueur",
      "palindromic.digit_length": "Nombre de chiffres",
      "palindromic.limit_reached": "Limite de {{max}} résultats atteinte",
      "palindromic.error_length": "La longueur doit être entre 1 et 20",
      "palindromic.waiting": "Configurez les options pour voir les nombres palindromes...",
      "palindromic.about_title": "À propos des nombres palindromes",
      "palindromic.about_text": "Un nombre palindrome est un nombre qui reste le même lorsqu'on inverse ses chiffres. Par exemple, 121 ou 12321. Cet outil vous aide à trouver tous les nombres palindromes dans une plage numérique donnée ou à en générer aléatoirement d'une longueur spécifique.",
      "asciidecimal.about_title": "À propos de la conversion ASCII/Décimal",
      "asciidecimal.about_text": "Cet outil permet un mappage bidirectionnel entre les caractères de texte et leurs codes décimaux correspondants. Il utilise la norme Unicode, qui couvre l'ASCII standard (0-127) ainsi que les caractères étendus et les emojis. Chaque caractère est représenté par son 'point de code' numérique.",
      "bitshifter.shift_type": "Type de décalage",
      "bitshifter.amount": "Valeur du décalage",
      "bitshifter.about_title": "À propos du décalage de bits",
      "bitshifter.about_text": "Le décalage bit à bit déplace chaque bit d'une chaîne binaire vers la gauche ou la droite. Les décalages logiques remplissent les espaces vides avec des zéros. Les décalages arithmétiques à droite préservent le bit de poids fort (MSB). Les rotations circulaires (ROL/ROR) réinjectent les bits sortants à l'autre extrémité.",
      "jsonflattener.about_title": "À propos de l'aplatissement JSON",
      "jsonflattener.about_text": "L'aplatissement convertit un JSON imbriqué en un objet à un seul niveau. Par exemple, {a: {b: 1}} devient {\"a.b\": 1}. C'est utile pour traiter le JSON dans des environnements qui ne supportent que des paires clé-valeur plates.",
      "jsonunflattener.about_title": "À propos du dépliage JSON",
      "jsonunflattener.about_text": "Le dépliage (unflattening) est l'inverse de l'aplatissement. Il prend un objet JSON plat où les clés représentent des chemins (ex: 'a.b.c') et le convertit en une structure JSON imbriquée. C'est utile pour traiter des données provenant de systèmes qui ne supportent que des paires clé-valeur plates mais représentent la hiérarchie via une notation par points.",
      "jsonsortkeys.sort_order": "Ordre de tri",
      "jsonsortkeys.ascending": "Croissant (A-Z)",
      "jsonsortkeys.descending": "Décroissant (Z-A)",
      "jsonsortkeys.recursive": "Tri récursif",
      "jsonsortkeys.about_title": "À propos du trieur de clés JSON",
      "jsonsortkeys.about_text": "Cet outil vous permet de trier les clés d'un objet JSON par ordre alphabétique. Trier les clés est extrêmement utile pour comparer deux fichiers JSON afin de voir les différences de données réelles sans être distrait par l'ordre des clés. Il peut trier récursivement les objets imbriqués et les tableaux d'objets.",
      "sierpinski.about_title": "À propos du triangle de Sierpinski",
      "sierpinski.about_text": "Le triangle de Sierpinski est une fractale auto-similaire, nommée d'après le mathématicien polonais Wacław Sierpiński qui l'a décrit en 1915. C'est un motif généré mathématiquement qui peut être reproduit à n'importe quelle échelle.",
      "jsonstringifier.about_title": "JSON Stringifier & Parser",
      "jsonstringifier.about_text": "Cet outil convertit un objet JSON en une chaîne de caractères entre guillemets avec des caractères échappés, ce qui est souvent nécessaire pour inclure du JSON dans d'autres structures JSON ou comme littéraux de chaîne dans le code source.",
      "htmlstripper.about_title": "À propos du nettoyeur HTML",
      "htmlstripper.about_text": "Cet outil supprime toutes les balises et attributs HTML de votre saisie, ne laissant que le contenu textuel. Il utilise le parseur DOM natif du navigateur pour une suppression performante et fiable.",
      "jsonflattener.separator": "Séparateur",
