      "iban_gen.placeholder": "L'IBAN généré apparaîtra ici...",
      "iban_gen.about_title": "À propos de la génération d'IBAN",
      "iban_gen.about_text": "L'International Bank Account Number (IBAN) est un système international d'identification des comptes bancaires. Cet outil génère des IBAN valides basés sur l'algorithme MOD-97. Note : Ces numéros sont destinés à des fins de test et d'éducation ; ils ne correspondent pas à de réels comptes bancaires.",
