      "jsontobigquery.about_text": "Google BigQuery utilise un format de schéma JSON pour les définitions de tables. Cet outil convertit votre structure JSON dans ce format, en identifiant des types comme STRING, INT64, FLOAT64, BOOL, et des types RECORD imbriqués.",
