      "cc_gen.placeholder": "Les détails de la carte apparaîtront ici...",
      "cc_gen.about_title": "À propos de la génération de Cartes",
      "cc_gen.about_text": "Cet outil génère des numéros de carte de crédit qui passent le test de l'algorithme de Luhn (MOD-10). Il fournit également un CVV et une date d'expiration aléatoires. Ces numéros sont destinés à des fins de développement et de test uniquement et ne peuvent pas être utilisés pour de réelles transactions.",
      "tool.atbash-cipher.name": "Chiffre Atbash",
      "tool.atbash-cipher.description": "Chiffre Atbash pour l'inversion de l'alphabet",
      "atbash.about_title": "C'est quoi le chiffre Atbash ?",
      "atbash.about_text": "Le chiffre Atbash est une méthode de cryptographie très ancienne et simple. Il consiste à inverser l'alphabet : la première lettre (A) devient la dernière (Z), la seconde (B) devient l'avant-dernière (Y), et ainsi de suite.",
      "tool.rail-fence-cipher.name": "Chiffre Rail Fence",
