      "railfence.about_title": "C'est quoi le chiffre Rail Fence ?",
      "railfence.about_text": "Le chiffre Rail Fence (aussi appelé chiffrement en zigzag) est une forme de chiffrement par transposition. Le texte est écrit en diagonale sur plusieurs 'rails' imaginaires, puis lu ligne par ligne pour produire le texte chiffré.",
