      "maze.algorithm_desc": "Cet outil utilise un algorithme de recherche en profondeur (DFS) avec une pile pour garantir que chaque partie du labyrinthe est accessible et sans boucles.",
      "maze.backtracking_title": "Retour sur Trace",
      "maze.backtracking_desc": "L'algorithme visite des voisins aléatoires et 'brise' les murs. S'il est bloqué, il revient en arrière jusqu'à trouver une cellule avec des voisins non visités.",
      "maze.perfect_maze_title": "Un Labyrinthe Parfait",
