      "nato.about_title": "C'est quoi ?",
      "nato.about_text": "L'alphabet phonétique de l'OTAN est un code utilisé par les armées et les services d'urgence pour épeler des mots sans erreur de compréhension, notamment lors de transmissions radio difficiles.",
