      "base64video.about_text": "Convertissez des chaînes encodées en Base64 en une vidéo lisible. Supporte les formats MP4, WebM et OGG. Pratique pour tester des flux vidéo provenant d'APIs ou de bases de données sans avoir à créer un fichier manuellement.",
      "base32.about_title": "À propos du Base32",
      "base32.about_text": "Le Base32 est un système de codage utilisant un alphabet de 32 caractères pour représenter des données binaires. Cet outil respecte la norme RFC 4648. Contrairement au Base64, le Base32 est insensible à la casse et évite les symboles ambigus, ce qui le rend plus lisible par l'homme et adapté aux noms de fichiers ou aux URLs.",
