      "punycode.about_title": "À propos du Punycode",
      "punycode.about_text": "Punycode est une représentation d'Unicode avec le sous-ensemble de caractères ASCII limité utilisé pour les noms de domaine Internet. En utilisant Punycode, les noms d'hôtes contenant des caractères Unicode sont transcodés en un sous-ensemble d'ASCII pour la compatibilité avec l'infrastructure DNS. Par exemple, \"mañana.com\" devient \"xn--maana-pta.com\".",
