      "css_filter.about_desc": "La propriété CSS filter applique des effets graphiques comme le flou ou le décalage de couleur à un élément. Les filtres sont couramment utilisés pour ajuster le rendu des images, des arrière-plans et des bordures.",
      "bezier.progression": "Progression",
