      "bezier.custom": "Bézier Personnalisé",
      "bezier.css_output": "Sortie CSS",
      "bezier.presets": "Préréglages",
      "bezier.about_text": "Une courbe de Bézier cubique est définie par quatre points : P0, P1, P2 et P3. P0 est fixé à (0,0) et P3 à (1,1). Cet outil vous permet de déplacer P1 et P2 pour définir le timing de vos transitions CSS.",
      "bezier.timing_title": "Timing de l'Animation",
      "bezier.timing_desc": "L'axe X représente le temps, et l'axe Y représente la progression de l'animation. Des valeurs hors de 0-1 sur l'axe Y créent des effets de rebond.",
      "bezier.interaction_title": "Interaction",
      "bezier.interaction_desc": "Faites glisser les cercles rouge et vert sur le canevas pour mettre à jour la courbe en temps réel. Utilisez les préréglages pour les fonctions d'assouplissement courantes.",
      "svg_to_css.mode_uri": "Encodé URI",
