      "svg_to_css.why_desc": "Les Data URIs permettent d'intégrer des images SVG directement dans vos fichiers CSS, réduisant ainsi le nombre de requêtes HTTP.",
      "svg_to_css.comparison_title": "URI vs Base64",
      "svg_to_css.comparison_desc": "Pour le SVG, l'encodage URI standard est généralement plus efficace que le Base64 car les SVG sont basés sur du texte.",
