      "lorentz.about_title": "Attracteur de Lorentz",
      "lorentz.about_desc": "L'attracteur de Lorenz est un ensemble de solutions chaotiques du système de Lorenz, un système de trois équations différentielles ordinaires.",
      "lorentz.chaos_title": "Théorie du Chaos",
      "lorentz.chaos_desc": "Le système est célèbre pour sa forme de papillon et pour illustrer l'effet papillon, où de petits changements initiaux mènent à des résultats très différents.",
      "integer_partitions.input_number": "Entier à partitionner",
      "integer_partitions.separator": "Séparateur de termes",
      "integer_partitions.error_too_large": "Nombre trop grand (max : {{max}}). Le nombre de partitions croît de manière exponentielle.",
      "integer_partitions.limit_reached": "Affichage des {{max}} premières partitions.",
      "integer_partitions.about_title": "À propos des Partitions d'Entier",
      "integer_partitions.about_text": "En théorie des nombres et en combinatoire, une partition d'un entier positif n est une façon de l'écrire comme une somme d'entiers positifs. Deux sommes qui ne diffèrent que par l'ordre de leurs termes sont considérées comme la même partition. Cet outil génère toutes les partitions possibles pour un nombre donné.",
      "hex_endianness.word_size": "Taille du mot",
      "hex_endianness.error_invalid_length": "La longueur de la chaîne hex doit être un multiple de {{bits}} bits ({{bytes}} caractères).",
      "hex_endianness.about_title": "À propos de l'Endianness Hex",
      "hex_endianness.about_text": "L'endianness (boutisme) désigne l'ordre dans lequel les octets sont organisés au sein d'unités de données plus grandes (mots) dans la mémoire d'un ordinateur. Le Big-endian stocke l'octet le plus significatif en premier, tandis que le Little-endian stocke l'octet le moins significatif en premier. Cet outil permet de basculer entre ces formats en inversant l'ordre des octets dans chaque mot.",
      "grapheme_extractor.extracted_title": "Graphèmes Extraits",
      "grapheme_extractor.about_title": "À propos de l'Extraction de Graphèmes",
      "grapheme_extractor.about_text": "Un graphème est la plus petite unité fonctionnelle d'un système d'écriture. Alors qu'un 'caractère' en code fait souvent référence à un seul point de code Unicode, les caractères perçus par l'utilisateur (comme les emojis combinés ou les lettres accentuées) peuvent être composés de plusieurs points de code. Cet outil utilise l'API Intl.Segmenter pour identifier correctement ces unités.",
      "number_rounding.method": "Méthode d'Arrondi",
      "number_rounding.method_round": "Arrondi (Plus proche)",
      "number_rounding.method_floor": "Plancher (Bas)",
      "number_rounding.method_ceil": "Plafond (Haut)",
      "number_rounding.method_trunc": "Tronquer",
      "number_rounding.precision": "Décimales",
      "number_rounding.about_title": "À propos de l'Arrondi de Nombres",
      "number_rounding.about_text": "Effectuez des arrondis par lots sur des listes de nombres. Vous pouvez choisir entre l'arrondi standard au plus proche, l'arrondi systématique vers le bas (plancher), vers le haut (plafond) ou simplement la suppression des décimales (tronquer). L'outil préserve le texte non numérique autour des nombres.",
      "wordsearch.words_label": "Mots (un par ligne)",
      "wordsearch.directions": "Directions Autorisées",
      "wordsearch.puzzle": "Grille",
      "wordsearch.hide_solution": "Masquer Solution",
      "wordsearch.show_solution": "Afficher Solution",
      "wordsearch.failed_words": "Mots non placés :",
      "wordsearch.word_list": "Trouvez ces mots :",
      "wordsearch.guide_text": "Saisissez une liste de mots dans le panneau de gauche. Ajustez la taille de la grille et les directions autorisées selon vos préférences. La grille se régénère automatiquement. Vous pouvez afficher la solution ou télécharger la grille sous forme d'image pour l'imprimer.",
      "wordsearch.complexity_title": "Personnalisation",
      "wordsearch.complexity_text": "Choisissez parmi les directions horizontales, verticales et diagonales. Augmentez la taille de la grille pour accueillir des mots plus longs ou une liste de mots plus importante. Si un mot ne peut pas être placé après 100 tentatives aléatoires, il apparaîtra dans la section 'mots non placés'.",
