      "rot.about_title": "À propos des chiffres ROT",
      "rot.about_text": "ROT (rotation de N places) est un chiffre de substitution simple qui remplace un caractère par un autre caractère situé à un nombre fixe de positions dans l'alphabet.",
      "rot.desc_rot13": "Décale les lettres A-Z de 13 places. Souvent utilisé pour masquer des spoilers.",
      "rot.desc_rot5": "Décale les chiffres 0-9 de 5 places.",
      "rot.desc_rot18": "Combinaison de ROT13 et ROT5.",
      "rot.desc_rot47": "Décale tous les caractères ASCII visibles (33-126) de 47 places.",
      "aes.encrypted_text": "Texte Chiffré (Base64)",
      "aes.input_placeholder": "Entrez le texte à chiffrer...",
