      "aes.about_title": "Chiffrement Sécurisé",
      "aes.about_text": "Cet outil utilise AES-256-GCM (Galois/Counter Mode), un algorithme de chiffrement authentifié moderne et hautement sécurisé. Les clés sont dérivées de votre mot de passe à l'aide de PBKDF2 avec 100 000 itérations et un sel aléatoire.",
      "aes.error_encrypt": "Le chiffrement a échoué : ",
      "aes.error_decrypt": "Le déchiffrement a échoué. Veuillez vérifier votre mot de passe et les données d'entrée.",
      "aes.waiting": "Le résultat du chiffrement/déchiffrement apparaîtra ici...",
      "yaml_csv.about_title": "Convertisseur YAML en CSV",
      "yaml_csv.about_text": "Cet outil convertit les données YAML au format CSV. Si le YAML contient un tableau d'objets, les clés seront utilisées comme en-têtes. S'il contient un seul objet, il sera traité comme une seule ligne. Les structures imbriquées sont aplaties en leur représentation textuelle.",
      "csv_yaml.about_title": "Convertisseur CSV en YAML",
      "csv_yaml.about_text": "Cet outil convertit les données CSV en un tableau d'objets YAML. La première ligne du CSV est utilisée comme clés pour chaque objet. Les valeurs numériques et booléennes sont automatiquement détectées et converties.",
