      "json_html.header": "Ligne d'en-tête",
      "json_html.full_html": "Document complet",
      "json_html.border": "Bordure de table",
      "json_html.padding": "Marge interne",
      "json_html.spacing": "Espacement",
      "json_html.about_title": "À propos de JSON en Table HTML",
      "json_html.about_text": "Cet outil convertit un tableau d'objets JSON en un élément HTML <table> standard. Il identifie automatiquement les clés pour créer les en-têtes de tableau. Vous pouvez choisir d'exporter uniquement l'extrait du tableau ou un document HTML5 complet. Toutes les conversions sont effectuées entièrement dans votre navigateur.",
      "properties_json.unflatten": "Déplier les clés",
      "properties_json.about_title": "À propos de Properties en JSON",
      "properties_json.about_text": "Convertissez des fichiers .properties de style Java en JSON structuré. Il prend en charge les séparateurs = et :, les commentaires commençant par # ou !, et le dépliage automatique des clés en notation par points (ex: app.name devient un objet imbriqué). L'outil dispose également d'une protection contre la pollution de prototype pour un dépliage sécurisé.",
      "ndjson.to_ndjson": "Vers NDJSON",
      "ndjson.to_json": "Vers Tableau JSON",
      "ndjson.about_title": "À propos de NDJSON (Newline Delimited JSON)",
      "ndjson.about_text": "NDJSON est un format pour stocker ou diffuser des données structurées. Chaque ligne du fichier est un objet JSON valide, séparé par un caractère de nouvelle ligne. Il est idéal pour les grands ensembles de données et les fichiers journaux car il permet de traiter les données ligne par ligne sans charger tout le fichier en mémoire.",
      "json_latex.hlines": "hlines (horiz.)",
      "json_latex.vlines": "vlines (vert.)",
      "json_latex.about_title": "À propos de JSON en LaTeX",
      "json_latex.about_text": "Cet outil convertit un tableau d'objets JSON en un environnement tabular LaTeX. Il gère l'échappement automatique des caractères spéciaux LaTeX comme &, %, et $. Vous pouvez activer ou désactiver les lignes horizontales (\\hline) et verticales selon le style de votre document. Parfait pour les articles académiques et la documentation technique.",
      "json_avro.about_title": "À propos de JSON en Avro",
      "json_avro.about_text": "Apache Avro est un système de sérialisation de données. Avro repose sur des schémas, qui sont définis en JSON. Cet outil vous aide à convertir vos données JSON d'exemple en une définition de schéma Avro (.avsc), en inférant automatiquement les types et en gérant les structures imbriquées.",
      "ipconverter.invalid_ip": "Adresse IPv4 invalide",
      "ipconverter.invalid_decimal": "IP Décimale invalide",
      "ipconverter.about_title": "À propos de la conversion IP",
      "ipconverter.about_text": "Une adresse IPv4 est essentiellement un nombre de 32 bits. Bien que nous l'écrivions habituellement en notation décimale à points (ex: 192.168.1.1) pour la lisibilité humaine, les ordinateurs la traitent souvent comme un seul entier, une valeur hexadécimale ou une chaîne binaire brute. Cet outil vous aide à convertir entre ces différentes représentations.",
      "tsv_json.about_title": "À propos de la conversion TSV <> JSON",
      "tsv_json.about_text": "Le format TSV (Tab-Separated Values) est couramment utilisé pour l'échange de données tabulaires. Cet outil permet une conversion bidirectionnelle entre le TSV et les tableaux JSON. Il détecte automatiquement les types et gère correctement l'échappement.",
      "tsv_csv.about_title": "À propos de la conversion TSV <> CSV",
      "tsv_csv.about_text": "Convertissez entre les valeurs séparées par des tabulations (TSV) et les valeurs séparées par des virgules (CSV). Le TSV est souvent utilisé dans les tableurs, tandis que le CSV est un standard universel pour l'échange de données.",
      "svg_to_image.source": "Source SVG",
      "svg_to_image.scale": "Échelle",
      "svg_to_image.info": "Collez votre code XML SVG pour le rendu sur un canevas. Vous pouvez agrandir l'image jusqu'à 5x pour des exports haute résolution. Supporte la transparence pour le format PNG.",
      "svg_to_image.quality_info": "Le processus de mise à l'échelle préserve la netteté vectorielle. La dimension maximale est limitée à 4096px pour garantir la stabilité et la performance du navigateur.",
      "xml_to_csv.about_title": "À propos de XML en CSV",
      "xml_to_csv.about_text": "Convertissez des structures de données XML en tableaux CSV plats. L'outil identifie automatiquement les éléments répétitifs pour les traiter comme des lignes.",
      "tool.xml-yaml.name": "XML <> YAML",
