      "tool.csv-transposer.name": "Transposeur CSV",
      "tool.csv-transposer.description": "Transposer les lignes et colonnes de données CSV/TSV",
      "ascii_to_image.about_title": "À propos de ASCII en Image",
      "ascii_to_image.about_text": "Transformez vos chaînes d'art ASCII en images. Utile pour les bannières ou la documentation. Tout le rendu est effectué localement.",
      "sudoku.solve": "Résoudre",
      "sudoku.validate": "Valider",
      "sudoku.example": "Exemple",
