      "sqltomermaid.about_title": "À propos de SQL vers diagramme ER Mermaid",
      "sqltomermaid.about_text": "Collez des instructions SQL CREATE TABLE à gauche pour générer instantanément la syntaxe du diagramme d'entité-relation conforme à Mermaid.js. Les contraintes de clé étrangère standalone et en ligne sont analysées et traduites en lignes de relation visuelle dans le diagramme. Vous pouvez copier-coller le résultat directement dans Notion, Obsidian, GitHub markdown, ou l'éditeur Live officiel de Mermaid !",
