      "textcolumnsaligner.about_text": "Alignez les colonnes dans un texte séparé par des caractères. Cet utilitaire lit les tables brutes ou les sorties de terminaux et formate chaque colonne en ajoutant des espaces pour un alignement vertical parfait, rendant les logs bruts ou listes très faciles à lire.",
      "tool.water-calculator.name": "Besoins en Eau",
