      "water.why_title": "Pourquoi boire ?",
      "water.why_desc": "L'eau représente environ 60% du poids d'un adulte. Elle est essentielle pour la régulation thermique, le transport des nutriments et l'élimination des déchets.",
      "water.exercise_title": "L'effort physique",
      "water.exercise_desc": "Pendant l'exercice, vous perdez beaucoup d'eau par la sueur. Il est crucial d'augmenter votre consommation de 500ml à 1L par heure d'effort intense.",
      "water.health_title": "Hydratation et Santé",
      "water.health_desc": "Une bonne hydratation améliore la concentration, réduit la fatigue et peut aider à prévenir certains maux de tête et problèmes digestifs.",
      "water.tips_title": "Conseils pratiques",
      "water.tip_thirst": "N'attendez pas la soif",
