      "listseparatorchanger.separator_custom": "Personnalisé",
      "listseparatorchanger.about_title": "À propos du Changeur de Séparateur de Liste",
      "listseparatorchanger.about_text": "Convertissez facilement le délimiteur ou le séparateur entre les éléments d'une liste d'un format à un autre (par exemple, des valeurs séparées par des virgules en listes séparées par des sauts de ligne, ou des points-virgules en barres verticales). Comprend plusieurs options d'analyse et de nettoyage telles que le nettoyage des espaces, la suppression des éléments vides, la déduplication, le tri alphabétique ou numérique, le mélange aléatoire sécurisé et l'inversion de l'ordre.",
      "listreverser.input_label": "Liste d'Entrée",
