      "listreverser.about_text": "Un outil simple et efficace pour inverser l'ordre de n'importe quelle liste d'éléments. Choisissez simplement la façon dont la liste d'entrée est séparée (par virgule, point-virgule, tabulation, saut de ligne, chaîne personnalisée ou RegExp) et comment vous souhaitez formater la liste inversée en sortie.",
