      "xor.about_title": "À propos du chiffrement XOR et des opérations bit à bit",
      "xor.about_text": "Le XOR (OU exclusif) est une opération logique sur les bits. L'opération XOR bit à bit compare chaque bit des octets d'entrée avec le bit correspondant des octets de la clé. Si les bits sont différents, le bit de sortie est 1 ; s'ils sont identiques, la sortie est 0. Le XOR à clé répétitive applique la clé de manière cyclique sur toute la longueur de l'entrée, ce qui en fait un outil d'offuscation simple et très efficace, souvent utilisé en rétro-ingénierie, en analyse binaire et en démonstrations cryptographiques.",
