      "totp.about_title": "Comment fonctionne le TOTP (RFC 6238) ?",
      "totp.about_text": "Le mot de passe à usage unique basé sur le temps (TOTP) est une extension de l'algorithme HOTP, prenant en charge un facteur mobile basé sur le temps. Le secret est partagé en toute sécurité lors du jumelage, puis l'application et le serveur génèrent des jetons identiques synchronisés. Notre validateur tolère une dérive de temps d'un intervalle pour accommoder les retards réseau.",
