      "regexextractor.about_text": "Un outil extrêmement personnalisable, rapide et sécurisé pour rechercher, extraire, formater et dédupliquer des informations de fichiers texte bruts à l'aide d'expressions régulières. Extrayez des correspondances complètes, des groupes de capture numériques (comme $1, $2), des groupes de capture nommés, ou assemblez des chaînes personnalisées avec des modèles de remplacement complets. L'évaluation est effectuée de manière asynchrone à l'intérieur d'un Web Worker, garantissant une protection robuste contre le retour sur trace catastrophique (ReDoS) ou les blocages de thread.",
