      "collatz.about_title": "À propos de la conjecture de Collatz",
      "collatz.about_text": "La conjecture de Collatz est l'un des problèmes non résolus les plus célèbres en mathématiques. Également connu sous le nom de problème 3n + 1, il commence par n'importe quel entier positif n. Si n est pair, divisez-le par 2. Si n est impair, multipliez-le par 3 et ajoutez 1. La conjecture affirme que peu importe le nombre de départ, vous finirez toujours par atteindre 1. Ce visualiseur fournit des analyses riches, des évaluations de pic et des graphiques logarithmiques.",
