      "gzip_deflate.about_title": "À propos de la compression GZIP & DEFLATE",
      "gzip_deflate.about_desc1": "Gzip et Deflate sont des algorithmes de compression de données sans perte robustes et extrêmement courants basés sur les méthodologies de codage LZ77 et Huffman. Le format GZIP encapsule la charge utile Deflate avec des en-têtes système et une somme de contrôle de validation des erreurs.",
      "gzip_deflate.about_desc2": "Cet outil implémente la compression et la décompression bidirectionnelles hors ligne directement sur votre navigateur à l'aide des moteurs de flux client modernes. Aucune donnée n'est transmise à des serveurs distants, garantissant la sécurité et la confidentialité de vos fichiers.",
