      "jwk.info_title": "À propos des clés JSON Web (RFC 7517)",
      "jwk.info_desc_1": "Une clé JSON Web (JWK) est une structure de données JavaScript Object Notation (JSON) qui représente une clé cryptographique. Cet outil permet la génération sécurisée de clés personnalisées ou l'analyse hors ligne de définitions de clés privées ou publiques encodées en PEM standard. L'ensemble du calcul est exécuté localement dans le bac à sable de votre navigateur à l'aide de l'API window.crypto.",
      "jwk.security_warning": "Avertissement : Toutes les clés sont calculées localement et ne sont jamais envoyées à des serveurs externes. Cependant, faites toujours preuve d'une extrême prudence lors de la manipulation de clés privées de production sensibles sur n'importe quelle interface web.",
