      "jsobject.about_desc": "Cet outil vous permet de convertir facilement des objets littéraux JavaScript (souvent copiés depuis des consoles ou des fichiers de configuration) en formats JSON valides et vice-versa. Lors de la transformation vers un Objet JS, les guillemets sur les propriétés sont supprimés là où c'est valide, et des apostrophes simples standard sont préférées pour les valeurs textuelles.",
