i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources,
    fallbackLng: "fr",
    interpolation: {
      escapeValue: false
    },
    detection: {
      order: ['path', 'cookie', 'htmlTag', 'localStorage', 'navigator'],
      lookupFromPathIndex: 0,
    }
  });

export default i18n;
